package edu.pe.cibertec.saibm.membresia.infrastructure.config;
import java.time.Instant; import java.util.*; import org.springframework.transaction.annotation.Transactional; import edu.pe.cibertec.saibm.membresia.application.port.in.MembershipUseCase; import edu.pe.cibertec.saibm.membresia.application.usecase.MembershipService; import edu.pe.cibertec.saibm.membresia.domain.model.MembershipHistory;
@Transactional public class MembershipTransactionalFacade implements MembershipUseCase {private final MembershipService service;public MembershipTransactionalFacade(MembershipService s){service=s;}public List<PlanView> activePlans(Instant a){return service.activePlans(a);}public PlanView plan(UUID id){return service.plan(id);}public PlanView createPlan(PlanCommand c){return service.createPlan(c);}public PlanView updatePlan(UUID id,PlanCommand c){return service.updatePlan(id,c);}public void deactivatePlan(UUID id){service.deactivatePlan(id);}public AssignmentView assign(AssignmentCommand c,String k,String x){return service.assign(c,k,x);}public int expireDue(Instant a,String c){return service.expireDue(a,c);}public EntitlementView entitlement(String u,Instant a){return service.entitlement(u,a);}public List<MembershipHistory> history(String u){return service.history(u);}}
